DO $verified_migration$ DECLARE payload bytea := decode('', 'base64'); BEGIN
    IF encode(sha256(payload), 'hex') IS DISTINCT FROM '373f682e84fd7f3a1488134680ae7dddff75dc3314b92f6e6e8275ae320b3dd5' THEN
      RAISE EXCEPTION 'Migration payload SHA-256 mismatch';
    END IF;
    EXECUTE convert_from(payload, 'UTF8');
  END $verified_migration$;